package com.quantumweave.leadmanager.lead; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/leads") public class LeadController{private final LeadService s; public LeadController(LeadService s){this.s=s;}
@PostMapping @ResponseStatus(HttpStatus.CREATED) public Lead create(@Valid @RequestBody Lead l){return s.create(l);} @GetMapping public List<Lead> all(@RequestParam(required=false)String q){return s.all(q);} @GetMapping("/{id}") public Lead get(@PathVariable Long id){return s.get(id);} @PutMapping("/{id}") public Lead update(@PathVariable Long id,@Valid @RequestBody Lead l){return s.update(id,l);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.delete(id);}}
